package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("In la arko midhaha ugu horreeya", "Allahayow nagu barakee midhahayada, magaaladayadana ku barakee, sac iyo dhoobadeenana noogu barakee.", "Marka la arko midhaha ugu horreeya ee xilli ciyaareedka.", "Duco loogu duceeyo arsaaqda iyo magaalada qofka."),
        "dua_good_news" to DuaText("Markay Warka Raaxo", "Mahad dhamaanteed waxay u sugnaatay Eebbaha fadligiisa ku dhammaatay.", "Marka la helo bishaaro (oo sujuud shukriya).", "Nebigu ﷺ wuxuu yidhi sidan markuu arkay wax uu jeclaa."),
        "dua_looking_mirror" to DuaText("Isagoo ka eegaya Muraayada", "Allahayow sidaad muuqaalkayga u wanaajisay adna dabeecadeyda u wanaaji.", "Marka muraayadda laga eego.", "Nebigu ﷺ wuxuu sameeyay ducadan (waxaa la aasaasay xitaa iyada oo aan la xusin muraayad)."),
        "dua_rabbana_taqabbal" to DuaText("Aqbalaada Camalka", "Eebow tan naga aqbal; illeen adaa maqle og. Oo towbada naga aqbal; illeen adaa toobad aqbale Naxariista ah.", "Waxaa la weydiiyey Ibraahim iyo Ismaaciil (AS) isagoo kacbada dhisaya.", "Duco lagu aqbalo camal kasta oo wanaagsan ka dib."),
        "dua_muawwidhat" to DuaText("Saddexda Qul (Mucawwidhat)", "(Suuradda al-Ikhlaas) waxaad dhahdaa waa Eebaha kalida ah. Eebbow isku filan. Isagu ma dhasho mana dhasho. Wax la mid ahna ma jiro.\n\n(Suuratul Falaq) waxaad dhahdaa waxaan ka magan galay Eebaha waagu baryay sharka wuxuu abuuray, xumaanta mugdiga markuu dego, xumaanta kuwa garaaca guntimaha, iyo sharka xaasidku markuu xasdo.\n\n(Suuradda An-Nas) waxaad dhahdaa waxaan ka magan galay Eebaha Basharka, Boqorka Basharka, Eebaha Insiga, sharkiisa mid been abuur ah, ee ku waswaasinaya quluubta insiga, Jinni iyo Insiba.", "Saddexda suuradood subax kasta iyo galab kasta saddex jeer, hurdada ka horna ku afuufo gacmaha oo jidhka ka masax.", "Akhrin saddex jeer aroor iyo galabba ayaa ku filan wax walba."),
        "dua_sabr" to DuaText("Samir iyo samir", "Eebow ku shub korkanaga samir, sugo cagahaaganagana nooga gargaar qoomka gaalada ah.", "Xiliga dhibka iyo iska hor imaadka.", "Ducadii ciidanka Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Cafiska iyo ka ilaalinta Naarta", "Eebow waan rumaynay ee noo dambi dhaaf, naga ilaali cadaabka naarta.", "Ducada quraanka.", "Duco lagu sheegay sifooyinka kuwa Alle ka cabsada."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Hanuuninta Arinkeena (Ashab al-Kahf)", "Eebow noo Naxariiso Naftaada, Noona Darji Amarkeena Hanuun toosan.", "Ducada Reer Godka.", "Tilmaanta go'aamada iyo xaaladaha adag."),
        "dua_musa_faqir" to DuaText("Ducada Muuse (AS) ee rizqiga", "Eebbow waxaan u baahanahay wax kasta oo khayr ah oo aad ii soo dejiso.", "Raadso rizqi iyo wanaag - ducadii Muuse (AS) ee Madyan.", "Ducadaas ka dib, Alle wuxuu Muuse (AS) siiyay guri, shaqo iyo xaas."),
        "dua_ayyub" to DuaText("Ducadii Ayuub (AS) ee Xanuunka", "(Eebbow) waxaa i taabtay dhib, Adiguna waxaad tahay Naxariista kuwa naxariista.", "Xanuun iyo rafaad.", "Allaha ka saaray dhibtii Ayuub (AS)."),
        "dua_husn_khatimah" to DuaText("Dhimasho adigoo Muslim ah (Yuusuf AS)", "Abuuraha Cirka iyo Dhulka Adaa Gargaare ii ah Aduun iyo Aakhiraba. Igu dilo aniga oo Muslim ah oo igu biir kuwa xaqa ah.", "Duco wanaagsan oo ku dhamaada.", "Ducadii Nabi Yuusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Qaxoontiga sheydaanka", "Eebbow waxaan kaa magan galay shaydaanka xaswaaga, waxaana kaa magan galay Rabbiyow inay ii soo dhawaadaan.", "Ka magan galka shaydaanka.", "Ducada Qur'aanka ee magangelyo doon."),
        "dua_bad_character" to DuaText("Ka Qaxoontiga Dabeecada Xun", "Allow waxaan kaa magan galayaa akhlaaq xumo, camal xun iyo rabitaan xun.", "Ka carar dabeecad xumada, camalka iyo rabitaannada.", "Ducada Nabiga ﷺ."),
        "dua_zawal_nimah" to DuaText("Ka Badbaadinta Ducooyinka", "Allahayow waxaan kaa magan galayaa luminta nicmadaada, badalida wanaaga aad bixisay, cadaabkaada degdega ah iyo cadhadaada oo dhan.", "In laga magan galo duco iyo balaayo degdeg ah.", "Ducada Nabiga ﷺ."),
        "dua_useless_knowledge" to DuaText("Ka Qaxooti Aqoon Aan Faa'iido Lahayn", "Allahayow waxaan kaa magan galayaa cilmi aan anfacayn, qalbi aan cabsanayn, naf aan qancin, iyo duco aan laga jawaabin.", "Ka fogow cilmi aan waxba tarayn iyo qalbi aan Alle ka cabsi lahayn.", "Ducada Nabiga ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Aqoon Faa'iido Leh & Xalaal Rizq", "Allow waxaan ku waydiisanayaa cilmi faa'iido leh, rizqi saafi ah iyo camal la aqbalay.", "Salaadii Fajar kadib.", "Nebigu ﷺ waxa uu sidaa yidhi salaan fajar ka dib."),
        "dua_leprosy_diseases" to DuaText("Qaxootinimada Cudurada halista ah", "Allahayow waxaan kaa magan galayaa vitiligo, waali, baras iyo cudur kasta oo xun.", "Ka ilaalinta cudurada halista ah.", "Ducada sunnada ee ilaalinta caafimaadka."),
        "dua_fear_people" to DuaText("Cabsida Cadawga ama Dulmiga", "Allow hortooda ayaan ku dhignay, waxaana kaa magan galnay sharkooda.", "Marka laga baqayo dhibka dad ama qof.", "Nebigu ﷺ wuxuu sidaa yidhi markuu qoom ka cabsaday."),
        "dua_shirk_protection" to DuaText("Ka ilaalinta Shirkiga Qarsoon", "Allow waxaan kaa magan galayaa inaan adiga wax la wadaajiyo anoo ogaal ah, waxaanan dambi dhaaf ku waydiisanayaa wixii aan sameeyo anigoon ogayn.", "Si looga nabad galo istuska iyo shirkiga qarsoon.", "Shirki dahsoon ayaa ka qarsoomay quraanjada gurguurta."),
        "dua_rain" to DuaText("Marka Roobku Da'o", "Allahayow (soo dir) roob khayr qaba.", "Marka roobku da'o.", "Roobku waa xilli duco la aqbalo."),
        "dua_after_rain" to DuaText("Roobka kadib", "Waxaa naloo shubay roobka fadliga Alle iyo naxariistiisa.", "Roobka ka dib.", "Qofkii sidaas dhahaa waa mid Alle rumeeyay."),
        "dua_istisqa" to DuaText("Weydiinta Roobka (Istisqa)", "Allahayow roob (saddex jeer) nagu soo shub.", "Marka roob la waayo.", "Nabigu ﷺ ayaa ducadan ku tukaday khudbadii jimcaha oo uu da’ay."),
        "dua_heavy_rain" to DuaText("Roobab xad dhaaf ah", "Allahayow (ha ku soo daataan) hareerahayaga ee ha nagu dul dhicin.", "Marka roobku aad u badan yahay.", "Daruuruhu way dhaqaaqeen ducadii nabiga ﷺ."),
        "dua_wind" to DuaText("Markay Dabayshu Dhacdo", "Allahayow waxaan ku waydiisanayaa khayrkeeda, wanaaga ku jira iyo wanaaga waxa lagu soo diray, waxaana kaa magan galayaa xumaanteeda, xumaanteeda iyo xumaanta waxa lagu soo dirayba.", "Marka dabayl ama duufaan xoog leh ay dhacayso.", "Nebigu ﷺ wuxuu sameeyay ducadan xilli duufaano."),
        "dua_thunder" to DuaText("Onkodka Maqalka", "Waxaa nasahan Eebaha ay ku Tasbiixso onkodku mahadiisa, Malaa'igtuna ay ka Cabsi darteed.", "Markii la maqlay onkod - dhaqankii Cabdullaahi bin Zubayr (RA).", "Waxaa laga soo qaatay suuradda Ar-Raad (13:13)."),
        "dua_new_moon" to DuaText("Aragga Bisha Cusub", "Allahayow dayaxani ha inagu soo kordho barako, iimaan, badbaado iyo islaam. (Dayaxii,) Eebahay iyo Eebihiinba waa Alle.", "Marka la arko bisha cusub.", "Ducada sunnada ah ee bisha kasta."),
        "dua_janaza_adult" to DuaText("Salaada Janaza (Dadka)", "Allow noo dambi dhaaf inta nool iyo intii dhimatay, inta joogta iyo inta maqan, yar iyo weynba, rag iyo dumarba. Allahayow ruuxii aad noolayso oo naga mid ah Islaamka ha ku nooleeyo, ruuxii aad disho oo naga mid ah u dil iimaan.", "Kadib takbiirkii sadexaad ee salaada janaasada.", "Ducada sunnada ee qofka weyn ee dhintay."),
        "dua_janaza_child" to DuaText("Salaada Janaza (Ilmaha)", "Allow horgale (oo marti u ah) nooga yeel ajar iyo xasanaad, kana yeel mid shafeeco ah oo shafeecadiisa la aqbalo.", "Salaada janaasada ee ubadka (gabadha waxay dhahdaa ijcalaa).", "Ducada sunnada ah ee ay ku dhaqmaan Xanafiyadu."),
        "dua_mayyit_awf" to DuaText("Duco Faahfaahsan ee Marxuumka", "Allahayow u dambi dhaaf, una naxariiso, una naxariiso, una cafi. Soo dhawayntiisa ka dhig mid sharaf leh, oo qabrigiisana u waasici, isaga ku maydh biyo, baraf iyo roobdhagaxyaale, oo dembiyada ka nadiifi sida marada cad looga nadiifiyo wasakhda.", "Salaada janaasada ama marxuumka.", "Cawf bin Maalik (RA) wuxuu jeclaaday inuu ahaado qofkaas dhintay."),
        "dua_visiting_graves" to DuaText("Booqashada Qubuuraha", "Asalaamu caleykum dhamaan mu’miniinta iyo muslimiinta guryahaas degganow. Anaguna hadii Alle idmo waanu idinku soo biirin doonaa. Annaga iyo adinkaba waxaan Allaah uga baryayaa inuu kheyr ku siiyo.", "Marka la galayo xabaalaha.", "Xabaalaha oo la booqdo waxay xasuusisaa geerida iyo aakhiro."),
        "dua_closing_eyes" to DuaText("Marka la xiro Indhaha Marxuumka", "Allahayow u dambi dhaaf (magac), darajooyinkiisa ka koryeel kuwa hanuunsan, kuwa uu ka tagona ka mid noqo kuwa badala. Annaga iyo isaga u dambi dhaaf, Eebaha Caalamka; Qabrigiisa waasici oo nuur ka buuxi.", "Marka la xidho indhaha marxuumka (magaciisa xusaya).", "Nabiga ﷺ wuxuu u duceeyay Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Tacziya (Ta'ziyah)", "Eebbaa iska leh wuxuu qaatay, isagaa iska leh wuxuu siiyey, wax walbana agtiisa muddo magacaaban baa leh ee samir oo rajayn ajri.", "U tacsiyaynta qoys geeri ka dib.", "Nebigu ﷺ wuxuu fariintan u diray gabadhiisa."),
        "dua_placing_in_grave" to DuaText("In Marxuumka Qabriga la dhigo", "Bismilaahi wa inaa ilayhi raajicuun ﷺ.", "Marka lagu soo dejiyo marxuumka qabriga.", "Ducada sunnada ee xabaasha."),
        "dua_sneezing" to DuaText("Hidhisidda", "Mahad oo dhan Allaah ayaa iska leh. — Allow kuu naxariiso. — Alle ha ku hanuuniyo, arrimihiinana ha hagaajiyo.", "On hindhisada; Dhageystaha ayaa dhahaya Yarxamukallah, dabadeed kii hindhisay ayaa u jawaabay.", "Waa mid ka mid ah xuquuqda qofka muslimka ah uu ku leeyahay qofka muslimka ah."),
        "dua_toilet_enter" to DuaText("Gelida Musqusha", "Magaca Allaah. Allahayow waxaan kaa magan galay jinka nijaasta ah ee lab iyo dheddig.", "Kahor intaanad musqusha la gelin lugta bidix.", "Bismillah waxay noqotaa shaashad u dhaxaysa jinka iyo qofka."),
        "dua_toilet_exit" to DuaText("Ka bixitaanka Musqusha", "(Ilaahow,) waxaan kaa codsanayaa dambi dhaaf.", "Markaad musqusha uga baxayso cagta midig.", "Nebigu ﷺ wuxuu yidhi sidan markuu musqusha ka baxayay."),
        "dua_thanking" to DuaText("Mahadsanid Qof", "Allow khayr hakugu abaal mariyo.", "Marka qof kuu roonaado.", "Qofkii sidaas dhahaa si buuxda ayuu u mahad celiyay."),
        "dua_love_for_allah" to DuaText("Marka Qof Yidhaahdo 'Allaah Dartii Ayaan Ku Jeclahay'", "Eebbow, kan aad dartiis ii jeceshahay, ha ku jeclaado.", "Marka qof ku yiraahdo 'Allaah dartii ayaan kuu jeclahay'.", "Sunnada waxay ugu jawaabtay jacaylka Alle dartiis."),
        "dua_seeing_muslim_smile" to DuaText("Salaan (Salaan)", "Asalaamu Calaykum, Naxariista Eebe iyo Nimcadiisa.", "Marka qofka muslimka ah la kulmo.", "Salaan dhameestiran oo la dhaho waxay ku kasbatay soddon camal oo wanaagsan."),
        "dua_dressing" to DuaText("Labiska", "Mahad dhamaanteed waxay u sugnaatay Allahii ii huwisiyay tan oo igu arzuqeeyay ayada oo aan wax quwad iyo quwad toona lahayn.", "Markaad labisato.", "Bishaaro ku saabsan cafiska dembiyadii hore."),
    )
}
